import React from 'react';
import './ExpertiseForm.css';

const ExpertiseForm = ({ formData, setFormData, handleSubmit, isSubmitting, submitMessage }) => {
    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    return (
        <section className="expertise-form-section">
            <div className="expertise-form-container">
                <div className="form-content">
                    <h2 className="section-title">Экспертиза для вашего заведения</h2>
                    <p className="form-description">
                        Мы проводим объективную оценку ресторанов, баров и гастрономических пространств. 
                        Получите профессиональное заключение и размещение в нашем каталоге.
                    </p>
                </div>
                
                {submitMessage && (
                    <div className={`form-message ${submitMessage.includes('успешно') ? 'success' : 'error'}`}>
                        {submitMessage}
                    </div>
                )}
                
                <form className="expertise-form" onSubmit={handleSubmit}>
                    <div className="form-grid">
                        <div className="form-group">
                            <label htmlFor="name">Название заведения *</label>
                            <input
                                type="text"
                                id="name"
                                name="name"
                                value={formData.name}
                                onChange={handleChange}
                                required
                                placeholder="Введите название заведения"
                                disabled={isSubmitting}
                            />
                        </div>
                        
                        <div className="form-group">
                            <label htmlFor="city">Город *</label>
                            <input
                                type="text"
                                id="city"
                                name="city"
                                value={formData.city}
                                onChange={handleChange}
                                required
                                placeholder="Введите город"
                                disabled={isSubmitting}
                            />
                        </div>
                        
                        <div className="form-group">
                            <label htmlFor="contact_person">Контактное лицо *</label>
                            <input
                                type="text"
                                id="contact_person"
                                name="contact_person"
                                value={formData.contact_person}
                                onChange={handleChange}
                                required
                                placeholder="Введите ФИО контактного лица"
                                disabled={isSubmitting}
                            />
                        </div>
                        
                        <div className="form-group">
                            <label htmlFor="contact_phone">Телефон *</label>
                            <input
                                type="tel"
                                id="contact_phone"
                                name="contact_phone"
                                value={formData.contact_phone}
                                onChange={handleChange}
                                required
                                placeholder="+7 (___) ___-__-__"
                                disabled={isSubmitting}
                            />
                        </div>
                        
                        <div className="form-group full-width">
                            <label htmlFor="contact_email">Email *</label>
                            <input
                                type="email"
                                id="contact_email"
                                name="contact_email"
                                value={formData.contact_email}
                                onChange={handleChange}
                                required
                                placeholder="example@mail.ru"
                                disabled={isSubmitting}
                            />
                        </div>
                    </div>
                    
                    <div className="form-footer">
                        <p className="form-note">
                            *Отправляя заявку, вы соглашаетесь на обработку персональных данных
                        </p>
                        <button 
                            type="submit" 
                            className="submit-btn"
                            disabled={isSubmitting}
                        >
                            {isSubmitting ? 'Отправка...' : 'Отправить заявку'}
                        </button>
                    </div>
                </form>
            </div>
        </section>
    );
};

export default ExpertiseForm;
